(function runMailScript(current, template, email, email_action, event) {
    var linkedin = gs.getProperty('x_2223823_apollo_0.social.linkedin', 'https://www.linkedin.com/company/apollo-hospitals');
    var youtube = gs.getProperty('x_2223823_apollo_0.social.youtube', 'https://www.youtube.com/user/ApolloHospitalsIndia');
    var instagram = gs.getProperty('x_2223823_apollo_0.social.instagram', 'https://www.instagram.com/apollohospitals/');
    var facebook = gs.getProperty('x_2223823_apollo_0.social.facebook', 'https://www.facebook.com/TheApolloHospitals/');

    var iconStyle = 'display: inline-block; width: 28px; height: 28px; line-height: 28px; text-align: center; border-radius: 6px; background-color: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); color: #ffffff; text-decoration: none; font-size: 13px; font-weight: bold; margin-left: 6px;';

    template.print('<a style="' + iconStyle + '" title="LinkedIn" href="' + linkedin + '" target="_blank" rel="noopener">in</a>');
    template.print('<a style="' + iconStyle + '" title="YouTube" href="' + youtube + '" target="_blank" rel="noopener">&#9658;</a>');
    template.print('<a style="' + iconStyle + '" title="Instagram" href="' + instagram + '" target="_blank" rel="noopener">📷</a>');
    template.print('<a style="' + iconStyle + '" title="Facebook" href="' + facebook + '" target="_blank" rel="noopener">f</a>');
})(current, template, email, email_action, event);
